private static readonly SemaphoreSlim Slots = new(8, 8);

async Task HandleAsync(Request r, CancellationToken ct) {
    await Slots.WaitAsync(ct);          // never blocks a thread pool thread
    try { await ServeAsync(r, ct); }
    finally { Slots.Release(); }        // on success, failure and cancellation
}

